alter table public.service_requests add column if not exists latitude numeric(9,6) check (latitude is null or latitude between -90 and 90), add column if not exists longitude numeric(9,6) check (longitude is null or longitude between -180 and 180);
create table if not exists public.service_dispatch_config(id boolean primary key default true check(id),offer_timeout_seconds integer not null default 120 check(offer_timeout_seconds between 30 and 900),location_freshness_seconds integer not null default 180 check(location_freshness_seconds between 30 and 1800),min_location_update_seconds integer not null default 15 check(min_location_update_seconds between 5 and 300),default_travel_speed_kmh numeric(5,2) not null default 35 check(default_travel_speed_kmh between 5 and 120),updated_at timestamptz not null default now());
insert into public.service_dispatch_config(id) values(true) on conflict(id) do nothing;
create table if not exists public.service_provider_profiles(provider_id uuid primary key references auth.users(id) on delete cascade,business_id uuid not null references public.businesses(id) on delete cascade,availability_status text not null default 'UNAVAILABLE' check(availability_status in('AVAILABLE','UNAVAILABLE')),service_radius_km numeric(5,2) not null default 15 check(service_radius_km between 1 and 100),travel_speed_kmh numeric(5,2) not null default 35 check(travel_speed_kmh between 5 and 120),updated_at timestamptz not null default now());
create table if not exists public.service_provider_capabilities(provider_id uuid not null references public.service_provider_profiles(provider_id) on delete cascade,service_id uuid not null references public.services(id) on delete cascade,created_at timestamptz not null default now(),primary key(provider_id,service_id));
create table if not exists public.service_provider_locations(provider_id uuid primary key references public.service_provider_profiles(provider_id) on delete cascade,latitude numeric(9,6) not null check(latitude between -90 and 90),longitude numeric(9,6) not null check(longitude between -180 and 180),accuracy_m numeric(8,2) check(accuracy_m is null or accuracy_m>=0),recorded_at timestamptz not null,updated_at timestamptz not null default now());
create table if not exists public.service_dispatch_jobs(id uuid primary key default gen_random_uuid(),request_id uuid not null unique references public.service_requests(id) on delete cascade,status text not null default 'SEARCHING' check(status in('SEARCHING','PROVIDER_OFFERED','ASSIGNED','IN_PROGRESS','COMPLETED','CANCELLED','EXHAUSTED')),scheduled_start_at timestamptz,estimated_duration_minutes integer check(estimated_duration_minutes is null or estimated_duration_minutes>0),claimed_provider_id uuid references auth.users(id),claimed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.service_dispatch_offers(id uuid primary key default gen_random_uuid(),job_id uuid not null references public.service_dispatch_jobs(id) on delete cascade,provider_id uuid not null references public.service_provider_profiles(provider_id) on delete cascade,status text not null default 'OFFERED' check(status in('OFFERED','ACCEPTED','DECLINED','EXPIRED','REJECTED')),offered_at timestamptz not null default now(),expires_at timestamptz not null,eta_seconds integer not null check(eta_seconds>=0),location_age_seconds integer not null check(location_age_seconds>=0),compatibility_score integer not null check(compatibility_score between 0 and 100),expected_job_value numeric(12,2),estimated_duration_minutes integer,responded_at timestamptz);
create table if not exists public.service_dispatch_assignments(id uuid primary key default gen_random_uuid(),job_id uuid not null unique references public.service_dispatch_jobs(id) on delete cascade,provider_id uuid not null references public.service_provider_profiles(provider_id) on delete cascade,scheduled_start_at timestamptz,scheduled_end_at timestamptz,started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create index if not exists service_dispatch_jobs_status_idx on public.service_dispatch_jobs(status,updated_at desc); create index if not exists service_dispatch_offers_job_rank_idx on public.service_dispatch_offers(job_id,status,eta_seconds,location_age_seconds,compatibility_score); create index if not exists service_provider_capabilities_service_idx on public.service_provider_capabilities(service_id,provider_id); create index if not exists service_provider_profiles_available_idx on public.service_provider_profiles(provider_id,updated_at desc) where availability_status='AVAILABLE'; create unique index if not exists service_dispatch_one_live_offer_per_provider_idx on public.service_dispatch_offers(job_id,provider_id) where status='OFFERED'; create unique index if not exists service_dispatch_one_active_assignment_per_provider_idx on public.service_dispatch_assignments(provider_id) where completed_at is null;
alter table public.service_dispatch_config enable row level security; alter table public.service_provider_profiles enable row level security; alter table public.service_provider_capabilities enable row level security; alter table public.service_provider_locations enable row level security; alter table public.service_dispatch_jobs enable row level security; alter table public.service_dispatch_offers enable row level security; alter table public.service_dispatch_assignments enable row level security; revoke all on public.service_dispatch_config,public.service_provider_profiles,public.service_provider_capabilities,public.service_provider_locations,public.service_dispatch_jobs,public.service_dispatch_offers,public.service_dispatch_assignments from anon,authenticated;
create policy service_provider_profiles_self on public.service_provider_profiles for select to authenticated using(provider_id=(select auth.uid())); create policy service_provider_capabilities_self on public.service_provider_capabilities for select to authenticated using(provider_id=(select auth.uid())); create policy service_provider_locations_self on public.service_provider_locations for select to authenticated using(provider_id=(select auth.uid())); create policy service_dispatch_jobs_customer_or_provider on public.service_dispatch_jobs for select to authenticated using(exists(select 1 from public.service_requests r where r.id=request_id and r.customer_id=(select auth.uid())) or claimed_provider_id=(select auth.uid())); create policy service_dispatch_offers_provider on public.service_dispatch_offers for select to authenticated using(provider_id=(select auth.uid())); create policy service_dispatch_assignments_provider on public.service_dispatch_assignments for select to authenticated using(provider_id=(select auth.uid()));